import{_ as l,C as h,o as d,c,a2 as a,b as i,w as t,a as s,E as n,a3 as r}from"./chunks/framework.CZqXuAiL.js";const v=JSON.parse('{"title":"Configuration Reference","description":"Every Bandwidth Monitor configuration value documented — node config.yaml keys, the pairing token file, panel settings, and per-server limit overrides.","frontmatter":{"title":"Configuration Reference","description":"Every Bandwidth Monitor configuration value documented — node config.yaml keys, the pairing token file, panel settings, and per-server limit overrides.","head":[["meta",{"name":"og:title","content":"Bandwidth Monitor — Configuration Reference"}],["meta",{"name":"og:description","content":"Every node config.yaml key, panel setting, and per-server override for the Pterodactyl Bandwidth Monitor addon."}]]},"headers":[],"relativePath":"pterodactyl-bandwidth-monitor/configuration/reference.md","filePath":"pterodactyl-bandwidth-monitor/configuration/reference.md","lastUpdated":1785221274000}'),p={name:"pterodactyl-bandwidth-monitor/configuration/reference.md"};function u(g,e,b,k,m,y){const o=h("Mermaid");return d(),c("div",null,[e[2]||(e[2]=a('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><p>Bandwidth Monitor is configured at <strong>three layers</strong>, each documented in full below:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Where</th><th>Scope</th></tr></thead><tbody><tr><td><strong>Node config</strong></td><td><code>/etc/bandwidth-node/config.yaml</code> on each Wings node</td><td>How the agent runs: polling, logging, API bind, panel connection</td></tr><tr><td><strong>Panel settings</strong></td><td>Admin → Bandwidth → <strong>Settings</strong> tab</td><td>Global default speeds, quotas, exceed action, timezone, retention</td></tr><tr><td><strong>Per-server overrides</strong></td><td>Admin → server → <strong>Build</strong> tab → Bandwidth Limits</td><td>Limits for one server, overriding the global defaults</td></tr></tbody></table>',3)),(d(),i(r,null,{default:t(()=>[n(o,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20PS%5B%22Panel%20settings%3Cbr%2F%3E(bandwidth_settings%20table)%22%5D%20--%3E%20DEF%5B%22Global%20defaults%22%5D%0A%20%20%20%20DEF%20--%3E%20BC%5B%22Server%20create%2Fbuild%20form%3Cbr%2F%3Eprefilled%20bandwidth%5B...%5D%20fieldset%22%5D%0A%20%20%20%20BC%20--%3E%20ROW%5B%22bandwidth_server_limits%20row%3Cbr%2F%3E(per-server%20override)%22%5D%0A%20%20%20%20PS%20--%3E%7C%22limits%20payload%3Cbr%2F%3Econfig_version%20%2B%20timezone%22%7C%20NODE%5B%22Node%20agent%3Cbr%2F%3Econfig.yaml%20%2B%20%2Fetc%2Fbandwidth-node%2Ftoken%22%5D%0A%20%20%20%20ROW%20--%3E%20NODE%0A%20%20%20%20NODE%20--%3E%20TC%5B%22tc%20rules%20on%20container%20veth%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a('<div class="info custom-block"><p class="custom-block-title">ZERO MEANS UNLIMITED — EVERYWHERE</p><p>A speed or quota of <code>0</code> means <em>no limit and no tc rule</em> — on the node, in the panel settings, and in per-server overrides. Fresh installs ship all-zero defaults, so nothing is throttled until you set values.</p></div><hr><h2 id="node-config-etc-bandwidth-node-config-yaml" tabindex="-1">Node config: <code>/etc/bandwidth-node/config.yaml</code> <a class="header-anchor" href="#node-config-etc-bandwidth-node-config-yaml" aria-label="Permalink to &quot;Node config: `/etc/bandwidth-node/config.yaml`&quot;">​</a></h2><p>The installer (<code>install.sh</code>) writes this file during pairing. Any key you omit keeps its built-in default — a nearly empty file still runs. The daemon loads it on start:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bandwidth-noded</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/bandwidth-node/config.yaml</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # as run by systemd</span></span></code></pre></div><p>The config path can also be set with the <code>BANDWIDTH_NODE_CONFIG</code> environment variable. Durations use Go syntax (<code>5s</code>, <code>1m</code>, <code>1h</code>). After any change, restart the agent:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bandwidth-node.service</span></span></code></pre></div><h3 id="general" tabindex="-1"><code>general</code> <a class="header-anchor" href="#general" aria-label="Permalink to &quot;`general`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>general.socket_path</code></td><td>string</td><td><code>/var/run/bandwidth-node.sock</code></td><td>Unix socket the <code>bandwidth-node</code> CLI uses to talk to the daemon. The CLI overrides this with <code>BANDWIDTH_NODE_SOCKET</code> if set.</td></tr></tbody></table><details class="details custom-block"><summary>Common mistake — moving the socket without telling the CLI</summary><p>If you change <code>socket_path</code>, <code>bandwidth-node status</code> fails with &quot;cannot connect to daemon&quot; until you export <code>BANDWIDTH_NODE_SOCKET</code> to the new path. There is rarely a reason to move it.</p></details><h3 id="logging" tabindex="-1"><code>logging</code> <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;`logging`&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">logging</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">info</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  console</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/var/log/bandwidth-node/bandwidth-node.log</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_size_mb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_age_days</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_backups</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  compress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">json</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>logging.level</code></td><td>enum</td><td><code>info</code></td><td><code>debug</code>, <code>info</code>, <code>warn</code>, or <code>error</code>. Use <code>debug</code> only when diagnosing — it is noisy at a 5-second poll cadence.</td></tr><tr><td><code>logging.console</code></td><td>bool</td><td><code>true</code></td><td>Also log to stdout, which systemd captures into the journal (<code>journalctl -u bandwidth-node.service</code>).</td></tr><tr><td><code>logging.file</code></td><td>string</td><td><code>/var/log/bandwidth-node/bandwidth-node.log</code></td><td>Log file path. Rotated automatically using the keys below.</td></tr><tr><td><code>logging.max_size_mb</code></td><td>int</td><td><code>100</code></td><td>Rotate the log file once it reaches this size.</td></tr><tr><td><code>logging.max_age_days</code></td><td>int</td><td><code>30</code></td><td>Delete rotated logs older than this.</td></tr><tr><td><code>logging.max_backups</code></td><td>int</td><td><code>10</code></td><td>Maximum number of rotated files kept.</td></tr><tr><td><code>logging.compress</code></td><td>bool</td><td><code>true</code></td><td>Gzip rotated log files.</td></tr><tr><td><code>logging.format</code></td><td>enum</td><td><code>json</code></td><td><code>json</code> (machine-parsable, default) or <code>text</code>.</td></tr></tbody></table><h3 id="database" tabindex="-1"><code>database</code> <a class="header-anchor" href="#database" aria-label="Permalink to &quot;`database`&quot;">​</a></h3><p>The agent persists counters, limits, enforcement flags, and the outbound event queue in a local SQLite database, so enforcement <strong>survives restarts and panel outages</strong>.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/var/lib/bandwidth-node/bandwidth-node.db</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_open_conns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_idle_conns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  journal_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">WAL</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  synchronous</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NORMAL</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cache_size_kb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">32000</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  auto_migrate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>database.path</code></td><td>string</td><td><code>/var/lib/bandwidth-node/bandwidth-node.db</code></td><td>SQLite file location. Required.</td></tr><tr><td><code>database.max_open_conns</code></td><td>int</td><td><code>1</code></td><td>Max open SQLite connections. SQLite is single-writer — leave this at <code>1</code>.</td></tr><tr><td><code>database.max_idle_conns</code></td><td>int</td><td><code>1</code></td><td>Max idle connections kept in the pool.</td></tr><tr><td><code>database.journal_mode</code></td><td>enum</td><td><code>WAL</code></td><td><code>WAL</code>, <code>DELETE</code>, or <code>TRUNCATE</code>. WAL gives concurrent reads during writes; do not change without a reason.</td></tr><tr><td><code>database.synchronous</code></td><td>enum</td><td><code>NORMAL</code></td><td><code>OFF</code>, <code>NORMAL</code>, or <code>FULL</code>. <code>NORMAL</code> is the safe performance/crash-safety balance with WAL.</td></tr><tr><td><code>database.cache_size_kb</code></td><td>int</td><td><code>32000</code></td><td>SQLite page cache size in KiB (~31 MiB).</td></tr><tr><td><code>database.auto_migrate</code></td><td>bool</td><td><code>true</code></td><td>Apply schema migrations on startup. Keep enabled so upgrades work.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Setting <code>synchronous: OFF</code> trades durability for speed: a power cut can lose recent counters and queued events. <code>NORMAL</code> already survived production testing — don&#39;t tune this unless you know why.</p></div><h3 id="docker" tabindex="-1"><code>docker</code> <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;`docker`&quot;">​</a></h3><p>The agent talks to the <strong>local Docker CLI</strong> only — there are no endpoint or TLS knobs.</p><table tabindex="0"><thead><tr><th>Path</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>docker.discovery_interval</code></td><td>duration</td><td><code>10s</code></td><td>How often the agent rescans running containers. Only containers whose name (or a UUID-shaped label value) is a server UUID are managed — node system containers are ignored.</td></tr><tr><td><code>docker.watch_events</code></td><td>bool</td><td><code>true</code></td><td>Subscribe to the Docker event stream so new/removed containers are picked up immediately instead of waiting for the next rescan.</td></tr></tbody></table><h3 id="bandwidth" tabindex="-1"><code>bandwidth</code> <a class="header-anchor" href="#bandwidth" aria-label="Permalink to &quot;`bandwidth`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>bandwidth.poll_interval</code></td><td>duration</td><td><code>5s</code></td><td>Stats collection <strong>and</strong> quota-enforcement cycle. Must be positive.</td></tr></tbody></table><details class="details custom-block"><summary>When to change</summary><p><code>5s</code> was verified in production — a 10 Mbps cap held at ~9.5 Mbps and a 1 GiB quota tripped promptly. Raising the interval (e.g. <code>15s</code>) reduces CPU but delays quota enforcement; lowering it below <code>2s</code> is pointless churn.</p></details><h3 id="scheduler" tabindex="-1"><code>scheduler</code> <a class="header-anchor" href="#scheduler" aria-label="Permalink to &quot;`scheduler`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>scheduler.enabled</code></td><td>bool</td><td><code>true</code></td><td>Run the internal job scheduler (quota period resets, event queue delivery). Keep enabled.</td></tr><tr><td><code>scheduler.check_interval</code></td><td>duration</td><td><code>30s</code></td><td>How often scheduled jobs are evaluated.</td></tr></tbody></table><h3 id="cleanup" tabindex="-1"><code>cleanup</code> <a class="header-anchor" href="#cleanup" aria-label="Permalink to &quot;`cleanup`&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cleanup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1h</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  stale_server_hours</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">72</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  compact_db</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>cleanup.enabled</code></td><td>bool</td><td><code>true</code></td><td>Run periodic housekeeping.</td></tr><tr><td><code>cleanup.interval</code></td><td>duration</td><td><code>1h</code></td><td>How often the cleanup pass runs.</td></tr><tr><td><code>cleanup.stale_server_hours</code></td><td>int</td><td><code>72</code></td><td>Forget servers not seen for this many hours (deleted Pterodactyl servers). <code>0</code> = never forget.</td></tr><tr><td><code>cleanup.compact_db</code></td><td>bool</td><td><code>true</code></td><td>Compact the SQLite database during cleanup.</td></tr></tbody></table><details class="details custom-block"><summary>Common mistake — stale entries after deleting a server</summary><p>If you delete a server in the panel, its container disappears and the agent drops it from active management, but the record lingers for <code>stale_server_hours</code>. That&#39;s intentional: it protects quota counters if a container briefly vanishes during a Wings rebuild. Lower the value (e.g. <code>24</code>) only on very churny nodes.</p></details><h3 id="api" tabindex="-1"><code>api</code> <a class="header-anchor" href="#api" aria-label="Permalink to &quot;`api`&quot;">​</a></h3><p>The REST API the <strong>panel</strong> calls into. This is the panel&#39;s management interface to the node — keep it enabled and reachable.</p><table tabindex="0"><thead><tr><th>Path</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>api.enabled</code></td><td>bool</td><td><code>true</code></td><td>Serve the node REST API (<code>/api/v1/...</code>). Disabling it breaks panel stats, limit pushes, and unthrottle.</td></tr><tr><td><code>api.listen</code></td><td>string</td><td><code>0.0.0.0</code></td><td>Bind address. Required when the API is enabled. Bind to a private interface if your panel and nodes share one.</td></tr><tr><td><code>api.port</code></td><td>int</td><td><code>8480</code></td><td>Listen port (1–65535). This is what you entered during install.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">FIREWALL</p><p>The panel must be able to reach <code>http(s)://&lt;node&gt;:8480</code>. All endpoints require the bearer token <strong>except</strong> <code>GET /api/v1/health</code>, which is public and cheap — ideal for uptime probes.</p></div><h3 id="panel" tabindex="-1"><code>panel</code> <a class="header-anchor" href="#panel" aria-label="Permalink to &quot;`panel`&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">panel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://panel.example.com&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  token_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/bandwidth-node/token</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  heartbeat_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">60s</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>panel.url</code></td><td>string</td><td><em>(required — no default)</em></td><td>Panel base URL, e.g. <code>https://panel.example.com</code>. The daemon <strong>refuses to start</strong> without it.</td></tr><tr><td><code>panel.token_file</code></td><td>string</td><td><code>/etc/bandwidth-node/token</code></td><td>Path to the pairing token file (see below). Used for node → panel auth <strong>and</strong> to verify panel → node requests.</td></tr><tr><td><code>panel.heartbeat_interval</code></td><td>duration</td><td><code>60s</code></td><td>How often the agent posts a heartbeat (aggregate rates, throttled/exceeded counts) to the panel. Must be positive.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">HEARTBEAT DRIVES CONFIG SYNC</p><p>Every heartbeat response carries the panel&#39;s <code>config_version</code>. If it differs from the node&#39;s stored version, the agent immediately pulls <code>GET /limits</code> and re-applies rules — so panel changes land on the node within one heartbeat even if the direct push failed.</p></div><h3 id="traffic-control" tabindex="-1"><code>traffic_control</code> <a class="header-anchor" href="#traffic-control" aria-label="Permalink to &quot;`traffic_control`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>traffic_control.enabled</code></td><td>bool</td><td><code>true</code></td><td>Master switch for <code>tc</code> enforcement. When <code>false</code>, the agent still collects stats and reports to the panel but applies no shaping.</td></tr></tbody></table><h3 id="timezone" tabindex="-1"><code>timezone</code> <a class="header-anchor" href="#timezone" aria-label="Permalink to &quot;`timezone`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>timezone</code></td><td>string</td><td><code>UTC</code></td><td>Calendar quota-reset timezone: day = midnight, week = Monday 00:00, month = 1st 00:00. Must be a valid IANA name — the daemon fails validation otherwise.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">PANEL WINS</p><p>The panel sends its own configured timezone inside the limits payload, and that value overrides this key on the node. Set the timezone in the panel Settings tab; leave the node at <code>UTC</code>.</p></div><hr><h2 id="the-token-file-etc-bandwidth-node-token" tabindex="-1">The token file: <code>/etc/bandwidth-node/token</code> <a class="header-anchor" href="#the-token-file-etc-bandwidth-node-token" aria-label="Permalink to &quot;The token file: `/etc/bandwidth-node/token`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>Created by</td><td><code>install.sh</code> during pairing (you paste the token from the panel&#39;s Nodes page)</td></tr><tr><td>Format</td><td>64 lowercase hex characters (256-bit random)</td></tr><tr><td>Permissions</td><td><code>0600</code>, root-owned</td></tr><tr><td>Used for</td><td>Node → panel <code>Authorization: Bearer</code> header, and constant-time verification of panel → node API calls</td></tr></tbody></table><p>The panel stores only a <strong>bcrypt hash</strong> plus an encrypted copy (so you can re-view it in the panel). Resetting the token in the panel kills the old one immediately — after a reset you must write the new token into <code>/etc/bandwidth-node/token</code> and <code>systemctl restart bandwidth-node.service</code>, or the node goes offline.</p><div class="danger custom-block"><p class="custom-block-title">NEVER COMMIT OR SHARE THE TOKEN</p><p>Anyone with the token can read per-server traffic stats and push arbitrary limits to the node. Rotate it from the panel&#39;s Nodes page if it leaks.</p></div><hr><h2 id="panel-settings" tabindex="-1">Panel settings <a class="header-anchor" href="#panel-settings" aria-label="Permalink to &quot;Panel settings&quot;">​</a></h2><p>Admin → <strong>Bandwidth</strong> → <strong>Settings</strong> tab. These live in the <code>bandwidth_settings</code> table and are seeded by migration with the defaults below. Saving the form bumps <code>config_version</code> and pushes the new defaults to every online node.</p><h3 id="default-limits" tabindex="-1">Default limits <a class="header-anchor" href="#default-limits" aria-label="Permalink to &quot;Default limits&quot;">​</a></h3><p>Applied to every server that has <strong>no</strong> per-server override row.</p><table tabindex="0"><thead><tr><th>Setting key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>default_rx_speed_mbps</code></td><td>int</td><td><code>0</code></td><td>0–1,000,000</td><td>Download speed cap (Mbps) applied per server. <code>0</code> = unlimited.</td></tr><tr><td><code>default_tx_speed_mbps</code></td><td>int</td><td><code>0</code></td><td>0–1,000,000</td><td>Upload speed cap (Mbps) applied per server. <code>0</code> = unlimited.</td></tr><tr><td><code>default_exceed_action</code></td><td>enum</td><td><code>throttle</code></td><td><code>throttle</code> / <code>suspend</code> / <code>none</code></td><td>What happens when any quota is exceeded: <code>throttle</code> re-applies tc at the throttle speeds; <code>suspend</code> suspends the Pterodactyl server via the panel, then throttles to 1 Mbps; <code>none</code> records an event only.</td></tr><tr><td><code>default_throttle_rx_mbps</code></td><td>int</td><td><code>5</code></td><td>1–1,000,000</td><td>RX speed while throttled after a quota exceed.</td></tr><tr><td><code>default_throttle_tx_mbps</code></td><td>int</td><td><code>5</code></td><td>1–1,000,000</td><td>TX speed while throttled after a quota exceed.</td></tr></tbody></table><h3 id="default-quotas" tabindex="-1">Default quotas <a class="header-anchor" href="#default-quotas" aria-label="Permalink to &quot;Default quotas&quot;">​</a></h3><p>Six independent quotas — one per direction (RX/TX) per period (day/week/month). Values are in <strong>GiB</strong> (1024³ bytes) on both panel and node. <code>0</code> = unlimited.</p><table tabindex="0"><thead><tr><th>Setting key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>default_rx_quota_day_gb</code></td><td>int</td><td><code>0</code></td><td>Daily download allowance per server (GiB). Resets at midnight in the configured timezone.</td></tr><tr><td><code>default_rx_quota_week_gb</code></td><td>int</td><td><code>0</code></td><td>Weekly download allowance (GiB). Resets Monday 00:00.</td></tr><tr><td><code>default_rx_quota_month_gb</code></td><td>int</td><td><code>0</code></td><td>Monthly download allowance (GiB). Resets on the 1st at 00:00.</td></tr><tr><td><code>default_tx_quota_day_gb</code></td><td>int</td><td><code>0</code></td><td>Daily upload allowance per server (GiB).</td></tr><tr><td><code>default_tx_quota_week_gb</code></td><td>int</td><td><code>0</code></td><td>Weekly upload allowance (GiB).</td></tr><tr><td><code>default_tx_quota_month_gb</code></td><td>int</td><td><code>0</code></td><td>Monthly upload allowance (GiB).</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TESTED BEHAVIOR</p><p>On a live panel + Wings node: a 1 GiB quota exceeded throttled the server to 5 Mbps with <code>quota_exceeded</code> / <code>throttled</code> events visible in the panel, and a weekly quota exceed with <code>suspend</code> action produced a real server suspension. When a period resets, normal speeds are restored automatically and a <code>restored</code> event is emitted.</p></div><h3 id="collection-retention" tabindex="-1">Collection &amp; retention <a class="header-anchor" href="#collection-retention" aria-label="Permalink to &quot;Collection &amp; retention&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>timezone</code></td><td>string</td><td><code>UTC</code></td><td>any IANA timezone</td><td>Timezone in which day/week/month quota boundaries are evaluated. Sent to nodes in the limits payload, overriding the node&#39;s local <code>timezone</code> key.</td></tr><tr><td><code>poll_interval_seconds</code></td><td>int</td><td><code>60</code></td><td>15–3600</td><td>How often node agents heartbeat; also used as the panel-side stats poll interval (the panel polls each online node and stores rollups).</td></tr><tr><td><code>retention_days_hourly</code></td><td>int</td><td><code>90</code></td><td>1–3650</td><td>Days that hourly usage rollups (<code>bandwidth_usage_hourly</code>) are kept before pruning.</td></tr><tr><td><code>retention_days_daily</code></td><td>int</td><td><code>730</code></td><td>1–7300</td><td>Days that daily usage rollups (<code>bandwidth_usage_daily</code>) are kept. Two years covers most billing disputes.</td></tr></tbody></table><h3 id="config-version-—-how-changes-propagate" tabindex="-1"><code>config_version</code> — how changes propagate <a class="header-anchor" href="#config-version-—-how-changes-propagate" aria-label="Permalink to &quot;`config_version` — how changes propagate&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>config_version</code></td><td>int</td><td><code>0</code></td><td>Monotonic counter, <strong>managed by the panel — never edit by hand</strong>. Bumped atomically on every limits change (settings save, per-server override create/update/delete).</td></tr></tbody></table>',62)),(d(),i(r,null,{default:t(()=>[n(o,{id:"mermaid-1262",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20A%20as%20Admin%0A%20%20%20%20participant%20P%20as%20Panel%0A%20%20%20%20participant%20N%20as%20Node%20agent%0A%20%20%20%20A-%3E%3EP%3A%20Save%20settings%20%2F%20server%20override%0A%20%20%20%20P-%3E%3EP%3A%20config_version%20%2B%201%20(atomic)%0A%20%20%20%20P--%3E%3EN%3A%20PUT%20%2Fapi%2Fv1%2Flimits%20(immediate%20push%2C%20if%20node%20online)%0A%20%20%20%20Note%20over%20N%3A%20If%20push%20fails%20or%20node%20was%20offline%3A%0A%20%20%20%20N-%3E%3EP%3A%20POST%20%2Fheartbeat%20(every%2060%20s)%0A%20%20%20%20P--%3E%3EN%3A%20config_version%20in%20response%0A%20%20%20%20N-%3E%3EP%3A%20GET%20%2Flimits%20(version%20differs)%0A%20%20%20%20N-%3E%3EN%3A%20Persist%20to%20SQLite%20%2B%20re-apply%20tc%20rules%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=a('<p>This is why a node that was offline during a change still converges within one heartbeat of coming back — verified in production alongside pairing, stats flow, and admin unthrottle.</p><hr><h2 id="how-defaults-reach-a-server-—-and-how-to-override-them" tabindex="-1">How defaults reach a server — and how to override them <a class="header-anchor" href="#how-defaults-reach-a-server-—-and-how-to-override-them" aria-label="Permalink to &quot;How defaults reach a server — and how to override them&quot;">​</a></h2><p><strong>The create/build forms.</strong> The installer injects a <em>Bandwidth Limits</em> fieldset into the admin <strong>New Server</strong> and <strong>Build</strong> forms. On <em>New Server</em> the fields are prefilled from the global defaults; on <em>Build</em> they show the server&#39;s effective limits. Saving either form writes (or updates) a row in <code>bandwidth_server_limits</code>. Servers created over the API send no <code>bandwidth[...]</code> input and simply follow the live global defaults.</p><p><strong>The override row.</strong> Each field maps one-to-one onto the settings above:</p><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>server_id</code></td><td>int</td><td>—</td><td>The Pterodactyl server this row belongs to (unique; cascades on server deletion).</td></tr><tr><td><code>enabled</code></td><td>bool</td><td><code>true</code></td><td>Master switch for this server. <code>false</code> = agent collects stats but enforces nothing for this server.</td></tr><tr><td><code>rx_speed_mbps</code> / <code>tx_speed_mbps</code></td><td>int</td><td><code>0</code></td><td>Per-server speed caps. <code>0</code> = unlimited.</td></tr><tr><td><code>rx_quota_day_gb</code> / <code>rx_quota_week_gb</code> / <code>rx_quota_month_gb</code></td><td>int</td><td><code>0</code></td><td>Per-server RX quotas (GiB).</td></tr><tr><td><code>tx_quota_day_gb</code> / <code>tx_quota_week_gb</code> / <code>tx_quota_month_gb</code></td><td>int</td><td><code>0</code></td><td>Per-server TX quotas (GiB).</td></tr><tr><td><code>exceed_action</code></td><td>enum</td><td><code>throttle</code></td><td><code>throttle</code> / <code>suspend</code> / <code>none</code> for this server.</td></tr><tr><td><code>throttle_rx_mbps</code> / <code>throttle_tx_mbps</code></td><td>int</td><td><code>5</code></td><td>Speeds while this server is throttled.</td></tr></tbody></table><p><strong>Precedence is all-or-nothing per row:</strong> if a server has an override row, the <strong>entire</strong> effective limit set comes from that row — individual fields do <strong>not</strong> fall back to the global defaults. If the row is absent, the live global defaults apply, and deleting the row returns the server to defaults.</p><div class="warning custom-block"><p class="custom-block-title">ALL-OR-NOTHING OVERRIDES</p><p>Setting only <code>rx_speed_mbps: 100</code> on a server leaves its quotas at the row&#39;s own <code>0</code> (unlimited) — not at the global default quotas. Fill in every field you care about when creating an override.</p></div><p><strong>Change propagation.</strong> Any override write or delete bumps <code>config_version</code> and queues a limits push to the owning node when it&#39;s online; no-op writes (nothing actually changed) skip both. Changes land on the node within seconds — or at worst within one heartbeat.</p>',9))])}const E=l(p,[["render",u]]);export{v as __pageData,E as default};
